CREATE OR REPLACE FUNCTION public.fn_earn_get_link(p_business_slug text,p_name text,p_email text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog AS $$ DECLARE b public.businesses%ROWTYPE; r public.referrers%ROWTYPE; e text; n text:=btrim(coalesce(p_name,'')); BEGIN SELECT x.* INTO b FROM public.businesses x WHERE x.slug=lower(btrim(p_business_slug)) AND EXISTS(SELECT 1 FROM public.metros m WHERE m.is_live AND public.fn_earn_eligible(x,m)) LIMIT 1; IF b.id IS NULL THEN RAISE EXCEPTION 'not_on_earn'; END IF; IF NOT public.fn_rate_bucket_hit('earn_ip:'||public.fn_request_bucket(),interval '1 hour',10) OR NOT public.fn_rate_bucket_hit('earn_global',interval '1 hour',100) THEN RAISE EXCEPTION 'rate_limited'; END IF; IF public.fn_email_owned() THEN SELECT lower(email) INTO e FROM auth.users WHERE id=auth.uid(); ELSE e:=lower(btrim(coalesce(p_email,''))); END IF; IF e !~ '^[^@[:space:]]+@[^@[:space:]]+\.[a-z]{2,}$' OR length(e)>254 THEN RAISE EXCEPTION 'invalid_email'; END IF; SELECT * INTO r FROM public.referrers WHERE business_id=b.id AND lower(email)=e LIMIT 1; IF r.id IS NULL THEN IF length(n) NOT BETWEEN 2 AND 120 THEN RAISE EXCEPTION 'invalid_name'; END IF; r:=public.fn_upsert_referrer(b.id,n,e,NULL); END IF; IF public.fn_email_owned() THEN RETURN r.token; END IF; IF NOT EXISTS(SELECT 1 FROM public.suppressed_emails WHERE email=e) THEN PERFORM public.enqueue_email('transactional_emails',jsonb_build_object('to',e,'from','Revvin <info@revvin.co>','reply_to','info@revvin.co','subject','Your Revvin referral link','text','Your personal referral link: https://revvin.co/r/'||b.slug||'?ref='||r.token,'html','<p>Your personal referral link: <a href="https://revvin.co/r/'||b.slug||'?ref='||r.token||'">Open your link</a></p>','purpose','transactional','label','earn_link','queued_at',extract(epoch from now()),'message_id',gen_random_uuid()::text)); END IF; RETURN NULL; END $$;
REVOKE ALL ON FUNCTION public.fn_earn_get_link(text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_earn_get_link(text,text,text) TO anon,authenticated,service_role;
REVOKE INSERT ON public.funnel_events,public.mock_inquiries,public.callback_requests,public.email_leads FROM anon;